def split_csv(line):
    if line == '':
        return ['']

    n = len(line)
    i = 0
    fields = []

    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            buf = []
            closed = False
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    buf.append(line[i])
                    i += 1
            if not closed:
                return None
            # after closing quote must be comma or end
            if i < n and line[i] != ',':
                return None
            fields.append(''.join(buf))
        else:
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    return None
                i += 1
            fields.append(line[start:i])

        if i < n and line[i] == ',':
            i += 1
            if i == n:
                # trailing comma means an empty field follows
                fields.append('')
                break
            continue
        else:
            break

    return fields

